[InitializeOnLoad]public static class GridShiftV19SystemsChecks {
 static GridShiftV19SystemsChecks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("GS19Systems",false)){var go=new GameObject("Systems audit 19");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV19SystemsRunner>();}};}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");SessionState.SetBool("GS19Systems",true);GridShiftV19Film.Enabled=true;EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV19SystemsRunner:MonoBehaviour {
 StringBuilder report=new StringBuilder();float deadline;bool done;DeliveryManager m;GridShiftActiveOperations ops;
 void Check(bool ok,string message){report.AppendLine((ok?"PASS ":"FAIL ")+message);Write();if(!ok){Finish(false);throw new Exception(message);}}
