 void Finish(bool ok){if(done)return;done=true;Time.timeScale=1;report.AppendLine("RESULT "+(ok?"SUCCESS":"FAILURE"));Write();SessionState.SetBool("GS19Systems",false);EditorApplication.Exit(ok?0:1);}
 void Update(){if(!done&&deadline>0&&Time.realtimeSinceStartup>deadline)Check(false,"timeout da auditoria; pedido="+m?.orders.FirstOrDefault()?.status);}
