 IEnumerator Start(){deadline=Time.realtimeSinceStartup+420;GridShiftProfiles.RootOverride=Path.GetFullPath("Temp/GS19Systems-"+Guid.NewGuid().ToString("N"));GridShiftProfiles.Login("normal@audit.test","isolated",out _);GridShiftProfiles.Create(1,"Normal sentinel",false,out _);string normalPath=GridShiftProfiles.SlotPath(1),original=File.ReadAllText(normalPath),normalRoot=GridShiftProfiles.RootOverride;yield return new WaitForSeconds(3.5f);yield return GridShiftV19Film.Record("00-menu",Camera.main,3);var demo=Object.FindObjectsByType<Button>(FindObjectsSortMode.None).FirstOrDefault(b=>b.GetComponentInChildren<TMPro.TMP_Text>()?.text=="Nova demonstração SENAI");Check(demo!=null,"menu oferece sessão da feira sem exigir login");demo.onClick.Invoke();yield return Ready();Check(GridShiftFairSession.Active&&GridShiftProfiles.Root!=normalRoot&&m.Company.Employees==3&&m.Money==m.Company.Balance.startingCash,"demonstração usa empresa real com capital e equipe no perfil separado");Check(File.ReadAllText(normalPath)==original,"iniciar demonstração preserva bytes do slot normal");GridShiftTutorial.Skip();GridShiftOperationsUI.Instance.Close();var p=InteractionFocus.PlayerFor(m);p.BlockControls(false);var tablet=p.GetComponent<PortableTablet>();Check(tablet.Open(),"tablet real abre na sessão de feira");yield return new WaitForSeconds(.8f);foreach(string tab in new[]{"Visão Geral","Entregas","Frota","Financeiro","Funcionários","Missões","Upgrades","Mapa","Configurações"}){tablet.Operations.Show(tab);yield return null;Check(tablet.Operations.CurrentPage==tab,"aba real do tablet: "+tab);}
  tablet.Operations.Show("Frota");yield return GridShiftV19Film.Record("13-frota",Camera.main,4);tablet.Operations.Show("Funcionários");yield return GridShiftV19Film.Record("14-funcionarios",Camera.main,4);tablet.Operations.Show("Missões");yield return GridShiftV19Film.Record("15-missoes",Camera.main,4);tablet.Operations.Show("Upgrades");yield return GridShiftV19Film.Record("16-upgrades",Camera.main,4);tablet.Close();yield return new WaitForSeconds(.8f);
  yield return WorldSession.Instance.RequestTransition("Office",p.transform);yield return new WaitForSeconds(.3f);var filmedOffice=InteractionFocus.PlayerFor(m);var filmedTerminal=Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None).First(x=>x.gameObject.scene.name=="Office");filmedOffice.BlockControls(false);filmedTerminal.EnterComputer();yield return new WaitForSeconds(2);filmedTerminal.Operations.Show("Financeiro");yield return GridShiftV19Film.Record("18-office-financeiro",Camera.main,5);filmedTerminal.ExitComputer();yield return new WaitForSeconds(1);yield return WorldSession.Instance.RequestTransition("SampleScene",filmedOffice.transform);yield return new WaitForSeconds(.3f);p=InteractionFocus.PlayerFor(m);
  float funds=m.Money;Check(m.Company.Employee("rui",true,out _)&&m.Money<funds,"admissão real lança despesa");funds=m.Money;Check(!m.Company.Employee("rui",true,out _)&&m.Money==funds,"contratação repetida não cobra novamente");m.Company.Finance.Bill("audit19-bill","Conta isolada de verificação","Serviços",5,m.Company.Day+1,1);Check(m.Company.Finance.Pay("audit19-bill",out _),"conta existente pode ser paga");funds=m.Money;Check(!m.Company.Finance.Pay("audit19-bill",out _)&&m.Money==funds,"conta paga não cobra duas vezes");Check(!m.Company.Missions.Claim("factory-first",out _)&&m.Money==funds,"missão sem entrega real não concede recompensa");float oldVolume=GridShiftAudio.GetVolume("SFX");GridShiftAudio.SetVolume("SFX",.42f);Check(Mathf.Abs(GridShiftAudio.GetVolume("SFX")-.42f)<.001f,"volume usa configuração persistente");GridShiftAudio.SetVolume("SFX",oldVolume);
  var offer=m.Offers().Where(o=>o.weightKg>20&&o.weightKg<=m.truckThresholdKg).FirstOrDefault();Check(offer!=null&&m.Accept(offer.id,out _),"contrato automatizado real aceito com carga compatível");var order=m.orders.Last();string orderId=order.id;int acceptedCount=m.orders.Count;float beforeRepeat=m.Money;Check(m.Accept(offer.id,out _)&&m.orders.Count==acceptedCount&&m.orders.Count(x=>x.requestId=="offer:"+offer.id)==1&&m.Money==beforeRepeat,"repetir contrato retorna pedido existente sem duplicar operação ou dinheiro");float limit=Time.realtimeSinceStartup+15;while(string.IsNullOrEmpty(order.vehicleId)&&Time.realtimeSinceStartup<limit)yield return null;Check(!string.IsNullOrEmpty(order.vehicleId),"motorista disponível recebe veículo e rota reais");yield return new WaitForSeconds(.5f);DeliverySaveData saved=null;Check(m.GetComponent<DeliveryPersistence>().Save()&&DeliverySaveStore.Read(out saved),"save durante entrega automatizada");DeliverySaveStore.Pending=saved;yield return SceneManager.LoadSceneAsync("SampleScene",LoadSceneMode.Single);yield return Ready();order=m.orders.Single(x=>x.id==orderId);Check(!order.rewardPaid&&m.fleet.Count(v=>v.Order?.id==orderId)==1,"carregar mantém um veículo vinculado, sem pagar antecipadamente");GridShiftOperationsUI.Instance.Close();p=InteractionFocus.PlayerFor(m);var vehicle=m.fleet.Single(v=>v.Order?.id==orderId);yield return GridShiftV19Film.Record("17-operacao-automatica",Camera.main,6,false,(c,t)=>{var at=vehicle.transform.position;c.transform.position=at+vehicle.transform.TransformDirection(new Vector3(-7,3,-10));c.transform.LookAt(at+Vector3.up);});
  Time.timeScale=4;limit=Time.realtimeSinceStartup+160;var phases=new System.Collections.Generic.HashSet<DeliveryStatus>();while(order.status!=DeliveryStatus.Completed&&Time.realtimeSinceStartup<limit){phases.Add(order.status);yield return null;}Time.timeScale=1;report.AppendLine("TRACE automatic phases="+string.Join(",",phases)+" final="+order.status+" courier="+order.courierPhase);Write();Check(order.status==DeliveryStatus.Completed&&order.rewardPaid,"rota, coleta, transporte, descarga e retorno do entregador concluem operação real");funds=m.Money;m.Complete(order);Check(m.Money==funds&&m.Company.State.ledger.Count(x=>x.id=="delivery:"+orderId)==1,"pagamento automatizado permanece único");
  yield return WorldSession.Instance.RequestTransition("Office",p.transform);yield return new WaitForSeconds(.3f);var office=InteractionFocus.PlayerFor(m);var terminal=Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None).First(x=>x.gameObject.scene.name=="Office");office.BlockControls(false);terminal.EnterComputer();yield return new WaitForSeconds(2);Check(terminal.UsingComputer&&terminal.Operations!=null,"computador do Office usa interface nativa existente");terminal.Operations.Show("Financeiro");yield return new WaitForSeconds(.3f);Check(terminal.Operations.CurrentPage=="Financeiro","computador consulta financeiro sincronizado");terminal.ExitComputer();yield return new WaitForSeconds(1);yield return WorldSession.Instance.RequestTransition("SampleScene",office.transform);yield return new WaitForSeconds(.3f);Check(Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Count(x=>x.isActiveAndEnabled)==1,"um AudioListener após tablet, save e Office");
  var persistence=m.GetComponent<DeliveryPersistence>();Check(persistence.Save(),"save manual da demonstração concluída");GridShiftProfiles.Create(5,"Teste de exclusão isolado",false,out _);Check(!GridShiftProfiles.Delete(5,false,out _)&&File.Exists(GridShiftProfiles.SlotPath(5)),"exclusão exige confirmação");Check(GridShiftProfiles.Delete(5,true,out _)&&File.Exists(GridShiftProfiles.SlotPath(1)),"exclusão confirmada afeta somente slot escolhido");GridShiftProfiles.Activate(1,"Feira");
  int gc=GC.CollectionCount(0);long heap=UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong();float clock=Time.realtimeSinceStartup;for(int i=0;i<180;i++)yield return null;report.AppendLine("MEASURE editor 180 frames wallSeconds="+(Time.realtimeSinceStartup-clock)+" gen0Collections="+(GC.CollectionCount(0)-gc)+" managedHeap="+heap+" traffic="+Object.FindObjectsByType<TrafficCar>(FindObjectsSortMode.None).Length+" pedestrians="+Object.FindObjectsByType<PedestrianAgent>(FindObjectsSortMode.None).Length);Write();yield return GridShiftSession.ReturnToMenu();Check(!GridShiftFairSession.Active&&GridShiftProfiles.RootOverride==normalRoot&&File.ReadAllText(normalPath)==original,"retorno ao menu restaura raiz normal sem alterar o slot principal");Finish(true);
 }
